import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"routex/getting-started/faq.md","filePath":"routex/getting-started/faq.md","lastUpdated":1782667567000}'),n={name:"routex/getting-started/faq.md"};function o(r,e,h,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="does-routex-support-udp" tabindex="-1">Does RouteX support UDP? <a class="header-anchor" href="#does-routex-support-udp" aria-label="Permalink to &quot;Does RouteX support UDP?&quot;">​</a></h2><p>Yes. RouteX supports TCP, UDP, and TCP+UDP simultaneously on the same port range. UDP uses a session-based model with configurable idle timeout.</p><h2 id="can-i-run-multiple-proxies-at-once" tabindex="-1">Can I run multiple proxies at once? <a class="header-anchor" href="#can-i-run-multiple-proxies-at-once" aria-label="Permalink to &quot;Can I run multiple proxies at once?&quot;">​</a></h2><p>Yes. Each <code>.yaml</code> file in <code>configs/proxies/</code> is a separate proxy instance. They run in isolated goroutine groups — a panic in one never crashes others.</p><h2 id="how-does-hot-reload-work" tabindex="-1">How does hot reload work? <a class="header-anchor" href="#how-does-hot-reload-work" aria-label="Permalink to &quot;How does hot reload work?&quot;">​</a></h2><p>RouteX watches the proxies directory with inotify (fsnotify). When a proxy config file changes, only that proxy is reloaded. Existing connections continue until EOF or the drain timeout. The file watcher debounces rapid saves (200ms window).</p><h2 id="does-l7-protection-add-latency" tabindex="-1">Does L7 protection add latency? <a class="header-anchor" href="#does-l7-protection-add-latency" aria-label="Permalink to &quot;Does L7 protection add latency?&quot;">​</a></h2><p>No. The L7 engine wraps <code>net.Conn</code> with minimal overhead. The first read buffers N bytes for inspection, then forwards directly. Subsequent reads have zero inspection overhead. When L7 is disabled (<code>enabled: false</code>), the engine is never created.</p><h2 id="what-happens-when-bandwidth-quota-is-exceeded" tabindex="-1">What happens when bandwidth quota is exceeded? <a class="header-anchor" href="#what-happens-when-bandwidth-quota-is-exceeded" aria-label="Permalink to &quot;What happens when bandwidth quota is exceeded?&quot;">​</a></h2><p>If <code>suspend_on_limit: true</code>, the proxy stops accepting new connections. Existing connections complete normally. The proxy resumes automatically when the quota window resets (hourly at the top of the hour, daily at midnight in the configured timezone).</p><h2 id="can-i-manage-acl-rules-without-restarting" tabindex="-1">Can I manage ACL rules without restarting? <a class="header-anchor" href="#can-i-manage-acl-rules-without-restarting" aria-label="Permalink to &quot;Can I manage ACL rules without restarting?&quot;">​</a></h2><p>Yes. All 8 ACL API endpoints work live:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add a global blacklist rule</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: admin&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;action&quot;:&quot;deny&quot;,&quot;cidr&quot;:&quot;1.2.3.0/24&quot;,&quot;comment&quot;:&quot;bad subnet&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:9000/api/acl/global/rules</span></span></code></pre></div>`,14)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
